def caesar(cipher, s):
    out = []
    for ch in cipher:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch) - base - s) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

